bun -e '
import fs from "fs";
import path from "path";
const dir = "wiki/npcs";
const files = fs.readdirSync(dir).filter(f => f.endsWith(".md"));
const npcs = [];
for (const f of files) {
  const txt = fs.readFileSync(path.join(dir, f), "utf8");
  const name = txt.match(/^# (.+)/m)?.[1]?.trim();
  const lvl = txt.match(/\| \*\*Combat Level\*\* \| ([^|]+) \|/)?.[1]?.trim();
  const hp = txt.match(/\| \*\*Hitpoints\*\* \| ([^|]+) \|/)?.[1]?.trim();
  if (!lvl || lvl === "None") continue;
  const coords = [...txt.matchAll(/\((\d+),\s*(\d+)\)/g)].map(m => ({x: +m[1], z: +m[2]}));
  // Filter to surface or dungeon near F2P/mainland (x: 2900..3400, z: 3000..3600 or 9400..10000)
  const localCoords = coords.filter(c => c.x >= 2900 && c.x <= 3450 && ((c.z >= 3050 && c.z <= 3550) || (c.z >= 9450 && c.z <= 9950)));
  if (localCoords.length > 0) {
    npcs.push({ name, lvl, hp, sample: localCoords.slice(0, 3) });
  }
}
npcs.sort((a, b) => parseInt(a.lvl) - parseInt(b.lvl));
for (const n of npcs) {
  console.log(`${n.name.padEnd(25)} | Lvl: ${n.lvl.padEnd(8)} | HP: ${(n.hp||"?").padEnd(5)} | ${n.sample.map(c => `(${c.x},${c.z})`).join(", ")}`);
}
'

