async function killNpcSafe(pattern, maxMs = 30000) {
  const start = Date.now();
  let targetIndex = -1;
  let targetName = "";
  let targetLvl = 0;
  let lastX = sdk.getState()?.player?.worldX ?? 0;
  let lastZ = sdk.getState()?.player?.worldZ ?? 0;
  const startXp = sdk.getState()?.skills.find(sk => sk.name === 'Hitpoints')?.experience ?? 0;

  while (Date.now() - start < maxMs) {
    const s = sdk.getState();
    const px = s?.player?.worldX ?? 0;
    const pz = s?.player?.worldZ ?? 0;
    if (Math.hypot(px - lastX, pz - lastZ) > 35) {
      return { killed: false, died: true, name: targetName, level: targetLvl };
    }
    lastX = px;
    lastZ = pz;

    const npc = targetIndex !== -1
      ? s?.nearbyNpcs.find(n => n.index === targetIndex)
      : s?.nearbyNpcs.find(n => pattern.test(n.name) && n.options.includes('Attack') && !n.inCombat);
    if (!npc) {
      if (targetIndex !== -1) {
        const endXp = s?.skills.find(sk => sk.name === 'Hitpoints')?.experience ?? 0;
        return { killed: endXp > startXp, name: targetName, level: targetLvl, xpGained: endXp - startXp };
      }
      break;
    }
    targetIndex = npc.index;
    targetName = npc.name;
    targetLvl = npc.combatLevel;
    if (npc.maxHp > 0 && npc.hp === 0) {
      await sdk.waitForTicks(2);
      const endXp = sdk.getState()?.skills.find(sk => sk.name === 'Hitpoints')?.experience ?? 0;
      return { killed: true, name: targetName, level: targetLvl, xpGained: endXp - startXp };
    }
    if (!s?.player?.combat?.inCombat || s?.player?.interactingIndex !== (npc.index + 32768)) {
      const r = await bot.attack(npc);
      if (!r.success && /reach/i.test(r.message || "")) {
        return { killed: false, unreachable: true, name: targetName, level: targetLvl };
      }
    }
    // Check if quest message blocked attack
    const recentMsgs = sdk.getNewChat();
    if (recentMsgs.some(m => /cannot attack|don't need|no reason/i.test(m.text))) {
      return { killed: false, blocked: true, name: targetName, level: targetLvl };
    }
    await sdk.waitForTicks(2);
  }
  return { killed: false, name: targetName, level: targetLvl };
}

